/* --- Enhanced Print Styles --- */
@media print {
    /* 1. Reset Page Margins */
    @page { size: landscape; margin: 0 !important; }

    html, body { width: 100%; height: auto !important; margin: 0 !important; padding: 0 !important; background: white !important; overflow: visible !important; }

    /* Global Hide */
    .sidebar, .no-print, header button, .fixed-bottom, #initial-loader, .tab-nav, .floating-btn, .app-container > aside { display: none !important; }

    /* Layout Reset */
    .app-container, .main-content { display: block !important; height: auto !important; width: 100% !important; margin: 0 !important; padding: 0 !important; overflow: visible !important; }

    /* Color Adjustments */
    .bg-gradient-to-br, [class*="bg-gradient-"] { background: white !important; border: 2px solid #000 !important; color: black !important; box-shadow: none !important; }
    .text-white { color: black !important; }
    .card { box-shadow: none !important; border: 1px solid #ddd !important; padding: 0 !important; margin-bottom: 20px !important; break-inside: auto !important; background: white !important; }

    /* Print Visibility */
    .print-only { display: block !important; width: 100%; padding: 20px; }
    tr.print-only { display: table-row !important; }

    /* --- Certificate Mode --- */
    body.print-mode-certificates .normal-print-content { display: none !important; height: 0; overflow: hidden; }
    body.print-mode-certificates .certificate-print-content { display: block !important; }
    body.print-mode-certificates { font-size: 12pt !important; }

    /* Certificate Page */
    .certificate-page {
        position: relative;
        width: 100%;
        height: 100vh;
        margin: 0 !important;
        padding: 5mm 15mm !important; /* Reduced Vertical Padding */
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        page-break-after: always;
        break-after: page;
        overflow: hidden;
        background: white;
    }
    .certificate-print-content > .certificate-page:last-child { page-break-after: auto !important; break-after: auto !important; margin-bottom: 0 !important; }

    /* Certificate Header - Tightened */
    .certificate-header .print-title-container {
        border-bottom: none !important;
        padding-bottom: 0 !important;
        margin-bottom: 0 !important;
    }
    .certificate-header .print-title-container > div:nth-child(2) > div { margin-bottom: 0 !important; line-height: 1.2 !important; }
    /* Hide the empty title box in certificates */
    .certificate-header .print-title-container > div:nth-child(2) > div:last-child { display: none !important; }

    .certificate-header .print-logo-box { display: none !important; }

    .certificate-header h1 { 
        font-size: 26pt;
        font-weight: 900; 
        margin: 10px 0 10px 0 !important; /* Reduced margins */
        text-decoration: underline; 
        text-underline-offset: 6px;
        text-align: center;
    }

    /* Certificate Body - Tightened */
    .certificate-body { 
        font-size: 16pt;
        line-height: 1.25; /* Tighter line height */
        margin-top: 0; 
        text-align: right; 
        flex-grow: 1; 
        display: flex; 
        flex-direction: column; 
        justify-content: center;
    }

    .certificate-body p {
        margin-bottom: 6px !important; /* Reduced paragraph spacing */
        margin-top: 0 !important;
    }

    /* Policy List - Tightened */
    .policy-list-container { margin: 5px 0; }
    .policy-list { 
        list-style-type: decimal; 
        margin-right: 30px; 
        column-count: 2; 
        column-gap: 30px; 
        text-align: right;
    }
    .policy-list li {
        margin-bottom: 1px !important; /* Tighter list items */
        font-size: 14pt;
        break-inside: avoid;
    }

    /* Certificate Footer - Tightened */
    .certificate-footer { 
        margin-top: auto; 
        display: flex; 
        justify-content: space-between; 
        font-weight: bold; 
        font-size: 14pt;
        padding: 0 20px 10px 20px !important; /* Reduced padding */
    }
    /* Reduce space for signatures */
    .certificate-footer .text-center p.mb-8 { margin-bottom: 30px !important; }

    /* --- Table/Stats Print Styles --- */
    .print-table { width: 100%; border-collapse: collapse; border: 2px solid #000; font-size: 9pt; direction: rtl; margin-top: 10px; }
    .print-table th, .print-table td { border: 1px solid #666; padding: 8px; text-align: center !important; color: #000 !important; vertical-align: middle; }
    .print-table th { background-color: #f0f0f0 !important; font-weight: 800; white-space: nowrap; border-bottom: 2px solid #000; }
    thead { display: table-header-group !important; }
    tfoot { display: table-footer-group !important; }
    .print-header-row { display: table-row !important; border: none !important; }
    .print-header-cell { border: none !important; padding-bottom: 20px !important; background-color: white !important; }

    .print-title-container {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 20px;
        border-bottom: 3px double #000;
        padding-bottom: 15px;
        margin-bottom: 15px;
    }
    .print-logo-box {
        border: 1px solid #000;
        border-radius: 12px;
        padding: 5px;
        width: 60px;
        height: 60px;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .print-footer {
        position: fixed; bottom: 0; left: 0; right: 0;
        border-top: 1px solid #ccc; padding: 5px 20px;
        font-size: 8pt; color: #555;
        display: flex; justify-content: space-between; background: white;
    }
}

// --- Common Print Header Component ---
const PrintHeader = ({ title, subtitle }) => (
    <div className="print-title-container">
        <div className="print-logo-box right">
            <Icons.Logo size={40} />
        </div>
        <div className="print-header-center">
            <div style={{fontSize: '18pt', fontWeight: '800', marginBottom: '5px'}}>مستشفى المنيا الجامعى للعيون</div>
            <div style={{fontSize: '14pt', fontWeight: 'bold', marginBottom: '5px', color: '#333'}}>وحدة مكافحة العدوى</div>
            <div style={{fontSize: '12pt', fontWeight: 'bold', borderTop: '1px solid #000', paddingTop: '5px', marginTop: '5px', display: 'inline-block', paddingLeft: '20px', paddingRight: '20px'}}>
                {title} {subtitle && <span> - {subtitle}</span>}
            </div>
        </div>
        {/* Spacer or 2nd logo if needed, kept hidden for balance if using flex, but absolute positioning handles it now */}
    </div>
);

const PlanViewPage = ({ data }) => {
    const [activeMonth, setActiveMonth] = useState(new Date().getMonth() + 1);

    const allMonths = [...Array(12).keys()].map(i => i + 1);

    return (
        <div className="space-y-6 fade-in p-4 lg:p-6 pb-24 lg:pb-6 normal-print-content">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 slide-up no-print">
                <div>
                    <h2 className="text-xl lg:text-2xl font-bold text-slate-800">الخطة السنوية</h2>
                    <p className="text-sm text-slate-500">استعراض المواضيع التدريبية المقررة لكل شهر</p>
                </div>
            </header>

            {/* Interactive Tabs for View */}
            <div className="no-print flex gap-3 overflow-x-auto hide-scrollbar p-2 -mx-2 slide-up" style={{animationDelay: '0.1s'}}>
                {allMonths.map(m => (
                    <button key={m} onClick={() => setActiveMonth(m)}
                            className={`px-5 py-2.5 lg:px-6 lg:py-3 rounded-2xl text-xs lg:text-sm font-bold whitespace-nowrap transition-all duration-200 ${activeMonth === m ? 'bg-slate-800 text-white shadow-lg shadow-slate-300 scale-105' : 'bg-white text-slate-500 hover:bg-slate-100 hover:text-slate-800'}`}>
                        {ARABIC_MONTHS[m-1]}
                    </button>
                ))}
            </div>

            {/* View Mode (Single Month) */}
            <div className="no-print grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-6 slide-up" style={{animationDelay: '0.2s'}}>
                {data.categories.map(cat => {
                    const planItem = data.plan.find(p => p.Month == activeMonth && p.Category === cat);
                    return (
                        <div key={cat} className="card p-6 lg:p-8 hover:shadow-md transition-shadow duration-300 border-t-4 border-t-transparent hover:border-t-indigo-500">
                            <h3 className="text-lg lg:text-xl font-bold text-slate-800 mb-4 lg:mb-6 flex justify-between items-center">
                                {cat} 
                                <span className="text-slate-300"><Icons.Plan /></span>
                            </h3>
                            <div className="flex flex-wrap gap-2">
                                {planItem ? planItem.Policies.split(", ").map(p => (
                                    <span key={p} className="bg-indigo-50 text-indigo-700 px-3 py-2 lg:px-4 lg:py-2.5 rounded-xl text-xs lg:text-sm font-bold border border-indigo-100 shadow-sm">{p}</span>
                                )) : <div className="text-slate-400 italic text-xs lg:text-sm py-4 w-full text-center bg-slate-50 rounded-xl border border-dashed border-slate-200">لا توجد خطة لهذا الشهر</div>}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Print Mode (All Months - Matrix Table) */}
            <div className="print-only">
                <table className="print-table" style={{width: '100%', direction: 'rtl'}}>
                    <thead>
                        {/* Print Header inside thead to repeat on every page */}
                        <tr className="print-only print-header-row">
                            <th colSpan={data.categories.length + 1} className="print-header-cell">
                                <PrintHeader 
                                    title="الخطة السنوية" 
                                    subtitle={new Date().getFullYear()}
                                />
                            </th>
                        </tr>
                        <tr>
                            <th style={{width: '10%', backgroundColor: '#f3f4f6', fontWeight: 'bold'}}>الشهر</th>
                            {data.categories.map(cat => (
                                <th key={cat} style={{backgroundColor: '#f3f4f6', fontWeight: 'bold'}}>{cat}</th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {allMonths.map(m => (
                            <tr key={m}>
                                <td style={{fontWeight: 'bold', whiteSpace: 'nowrap'}}>{ARABIC_MONTHS[m-1]}</td>
                                {data.categories.map(cat => {
                                    const planItem = data.plan.find(p => p.Month == m && p.Category === cat);
                                    return (
                                        <td key={cat} style={{fontSize: '9pt', whiteSpace: 'pre-wrap', verticalAlign: 'top', padding: '8px'}}>
                                            {planItem ? planItem.Policies.split(", ").join("\n") : "-"}
                                        </td>
                                    );
                                })}
                            </tr>
                        ))}
                    </tbody>
                    <tfoot className="print-only" style={{display: 'table-footer-group'}}>
                        <tr>
                            <td colSpan={data.categories.length + 1} style={{border: 'none', padding: '0'}}>
                                <PrintFooter />
                            </td>
                        </tr>
                    </tfoot>
                </table>
            </div>
        </div>
    );
};

/* --- Enhanced Print Styles --- */
@media print {
    /* 1. Reset Page Margins */
    @page { size: landscape; margin: 5mm !important; }

    /* Disable animations/transforms which break table pagination/header repetition */
    *, *::before, *::after {
        animation: none !important;
        transition: none !important;
        transform: none !important; 
    }

    html, body { width: 100%; height: auto !important; margin: 0 !important; padding: 0 !important; background: white !important; overflow: visible !important; }

    /* Global Hide */
    .sidebar, .no-print, header button, .fixed-bottom, #initial-loader, .tab-nav, .floating-btn, .app-container > aside { display: none !important; }

    /* Layout Reset */
    .app-container, .main-content { display: block !important; height: auto !important; width: 100% !important; margin: 0 !important; padding: 0 !important; overflow: visible !important; }

    /* Color Adjustments */
    .bg-gradient-to-br, [class*="bg-gradient-"] { background: white !important; border: 2px solid #000 !important; color: black !important; box-shadow: none !important; }
    .text-white { color: black !important; }

    /* Card Reset for Print: FORCE DISPLAY BLOCK */
    .card { 
        box-shadow: none !important; 
        border: none !important; 
        padding: 0 !important; 
        margin: 0 !important; 
        break-inside: auto !important; 
        background: white !important; 
        display: block !important; /* CRITICAL for repeating headers */
        overflow: visible !important;
    }

    /* Print Visibility */
    .print-only { display: block !important; width: 100%; }
    tr.print-only { display: table-row !important; }

    /* --- Certificate Mode --- */
    body.print-mode-certificates .normal-print-content { display: none !important; height: 0; overflow: hidden; }
    body.print-mode-certificates .certificate-print-content { display: block !important; }
    body.print-mode-certificates { font-size: 12pt !important; }

    /* Certificate Page */
    .certificate-page {
        position: relative;
        width: 100%;
        height: 100vh;
        margin: 0 !important;
        padding: 5mm 15mm !important; 
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        page-break-after: always;
        break-after: page;
        overflow: hidden;
        background: white;
    }
    .certificate-print-content > .certificate-page:last-child { page-break-after: auto !important; break-after: auto !important; margin-bottom: 0 !important; }

    /* Certificate Header - Tightened */
    .certificate-header .print-title-container {
        border-bottom: none !important;
        padding-bottom: 0 !important;
        margin-bottom: 0 !important;
    }
    .certificate-header .print-title-container > div:nth-child(2) > div { margin-bottom: 0 !important; line-height: 1.2 !important; }
    /* Hide the empty title box in certificates */
    .certificate-header .print-title-container > div:nth-child(2) > div:last-child { display: none !important; }
    .certificate-header .print-logo-box { display: none !important; }

    .certificate-header h1 { 
        font-size: 26pt;
        font-weight: 900; 
        margin: 10px 0 10px 0 !important; 
        text-decoration: underline; 
        text-underline-offset: 6px;
        text-align: center;
    }

    /* Certificate Body */
    .certificate-body { 
        font-size: 16pt;
        line-height: 1.25;
        margin-top: 0; 
        text-align: right; 
        flex-grow: 1; 
        display: flex; 
        flex-direction: column; 
        justify-content: center;
    }

    .certificate-body p {
        margin-bottom: 6px !important; 
        margin-top: 0 !important;
    }

    /* Policy List */
    .policy-list-container { margin: 5px 0; }
    .policy-list { 
        list-style-type: decimal; 
        margin-right: 30px; 
        column-count: 2; 
        column-gap: 30px; 
        text-align: right;
    }
    .policy-list li {
        margin-bottom: 1px !important; 
        font-size: 14pt;
        break-inside: avoid;
    }

    /* Certificate Footer */
    .certificate-footer { 
        margin-top: auto; 
        display: flex; 
        justify-content: space-between; 
        font-weight: bold; 
        font-size: 14pt;
        padding: 0 20px 10px 20px !important; 
    }
    .certificate-footer .text-center p.mb-8 { margin-bottom: 30px !important; }

    /* --- Table/Stats Print Styles --- */
    .print-table { width: 100%; border-collapse: collapse; border: 2px solid #000; font-size: 9pt; direction: rtl; margin-top: 10px; }
    .print-table th, .print-table td { border: 1px solid #666; padding: 8px; text-align: center !important; color: #000 !important; vertical-align: middle; }
    .print-table th { background-color: #f0f0f0 !important; font-weight: 800; white-space: nowrap; border-bottom: 2px solid #000; }

    /* CRITICAL: display: table-header-group ensures header repeats on every page */
    thead { display: table-header-group !important; }
    tfoot { display: table-footer-group !important; }
    tr { break-inside: avoid; page-break-inside: avoid; }

    .print-header-row { display: table-row !important; border: none !important; }
    /* Updated Print Header Styles for Reliability */
    .print-header-cell { 
        border: none !important; 
        padding-bottom: 20px !important; 
        background-color: white !important; 
    }

    .print-title-container {
        position: relative;
        text-align: center;
        border-bottom: 3px double #000;
        padding-bottom: 10px;
        margin-bottom: 15px;
        width: 100%;
        display: block; /* Ensure it's block for table compatibility */
    }
    .print-logo-box {
        position: absolute;
        top: 0;
        right: 0;
        border: 1px solid #000;
        border-radius: 12px;
        padding: 5px;
        width: 60px;
        height: 60px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: white;
    }
    .print-header-center {
        width: 100%;
