const HistoryPage = ({ data }) => {
    const [filterCat, setFilterCat] = useState("الكل");
    const [filterMonth, setFilterMonth] = useState("الكل");
    const [searchTerm, setSearchTerm] = useState("");
    const showToast = useToast();

    const filteredLogs = useMemo(() => {
        return data.logs.filter(l => {
            const matchCat = filterCat === "الكل" || l.Category === filterCat;
            const matchMonth = filterMonth === "الكل" || l.Month == filterMonth;
            const matchSearch = !searchTerm || l.TraineeName.toLowerCase().includes(searchTerm.toLowerCase()) || l.Policies.toLowerCase().includes(searchTerm.toLowerCase());
            return matchCat && matchMonth && matchSearch;
        }).sort((a, b) => new Date(b.Date) - new Date(a.Date));
    }, [data.logs, filterCat, filterMonth, searchTerm]);

    // Unique trainees data for certificates
    const uniqueTraineesForCert = useMemo(() => {
        if (filterMonth === "الكل") return [];
        const groups = {};
        filteredLogs.forEach(log => {
            const name = log.TraineeName;
            if (!groups[name]) {
                groups[name] = {
                    name: name,
                    category: log.Category,
                    policies: new Set()
                };
            }
            if (log.Policies) {
                log.Policies.split(/,|،/).forEach(p => {
                    const trimmed = p.trim();
                    if (trimmed) groups[name].policies.add(trimmed);
                });
            }
        });
        return Object.values(groups)
            .sort((a, b) => a.name.localeCompare(b.name, 'ar'))
            .map(g => ({...g, policies: Array.from(g.policies)}));
    }, [filteredLogs, filterMonth]);

    const handlePdfSave = () => {
        if (filterCat === "الكل" || filterMonth === "الكل") {
            showToast("يرجى اختيار الفئة والشهر أولاً لطباعة الكشف والإفادات", "error");
            return;
        }

        if (uniqueTraineesForCert.length === 0 && filteredLogs.length === 0) {
             showToast("لا توجد بيانات للطباعة", "error");
             return;
        }

        // Update title for PDF filename
        document.title = `سجل_التدريب_${filterCat}_${getMonthName(filterMonth)}_${new Date().getFullYear()}`;

        // Print BOTH Table AND Certificates (Combined Mode)
        document.body.classList.remove('print-mode-certificates');
        document.body.classList.add('print-mode-combined');

        if (document.activeElement) document.activeElement.blur();

        setTimeout(() => {
            window.focus();
            window.print();
        }, 100);

        // Robust cleanup with 5s delay for mobile support
        setTimeout(() => {
             document.body.classList.remove('print-mode-combined');
        }, 5000);
    };

    const getMonthName = (m) => m === "الكل" ? "الكل" : ARABIC_MONTHS[parseInt(m) - 1];

    const getTraineeTitle = (cat) => {
        if (cat === "أطباء") return "الطبيب (ة)";
        if (cat === "تمريض") return "مستر (مس)";
        return "السيد (ة)";
    };

    return (
        <div className="space-y-4 lg:space-y-6 fade-in p-4 lg:p-6 pb-24 lg:pb-6 h-full flex flex-col print:block print:h-auto">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 slide-up no-print">
                 <div>
                    <h2 className="text-xl lg:text-2xl font-bold text-slate-800">سجل التدريب</h2>
                    <p className="text-slate-500 text-sm no-print">أرشيف كامل لجميع الجلسات التدريبية</p>
                </div>
                <div className="flex flex-wrap gap-2 text-sm w-full md:w-auto items-center">
                    <button onClick={handlePdfSave} className="no-print btn-secondary hover:text-indigo-600 flex-1 md:flex-none justify-center">
                        <Icons.Download /> <span className="whitespace-nowrap">حفظ كملف PDF</span>
                    </button>
                    <div className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl font-bold no-print border border-slate-200 shadow-sm flex-1 md:flex-none text-center whitespace-nowrap">{filteredLogs.length} سجل</div>
                </div>
            </header>

            <div className="card p-3 no-print slide-up" style={{animationDelay: '0.1s'}}>
                <div className="flex flex-col lg:flex-row gap-3">
                    <div className="relative flex-1 group">
                        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث في السجلات..." className="input-base pl-10 bg-white text-sm group-hover:shadow-sm" />
                        <div className="absolute right-3 top-3.5 text-slate-400 group-hover:text-indigo-500 transition-colors"><Icons.Search /></div>
                    </div>
                    <div className="flex gap-2 overflow-x-auto hide-scrollbar pb-1">
                        <select value={filterCat} onChange={e => setFilterCat(e.target.value)} className="input-base w-auto min-w-[120px] bg-white cursor-pointer text-sm hover:border-indigo-300">
                            <option value="الكل">كل الفئات</option>
                            {data.categories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <select value={filterMonth} onChange={e => setFilterMonth(e.target.value)} className="input-base w-auto min-w-[120px] bg-white cursor-pointer text-sm hover:border-indigo-300">
                            <option value="الكل">كل الشهور</option>
                            {ARABIC_MONTHS.map((m, i) => <option key={i+1} value={i+1}>{m}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            <div className="card flex-1 overflow-hidden flex flex-col print:shadow-none print:border-none print:overflow-visible slide-up" style={{animationDelay: '0.2s'}}>
                <div className="overflow-x-auto flex-1 print:overflow-visible">
                    <table className="w-full text-right border-collapse min-w-[600px] print:w-full print-table">
